import {Antenna,ArrowRight,ArrowUpRight,BookOpen,Check,CheckCircle2,ChevronRight,CircuitBoard,Cpu,Download,Expand,FlaskConical,GitBranch,Pause,PenLine,Play,Radio,RotateCcw,Send,SkipBack,SkipForward,Type,Waves,ZoomIn,ZoomOut} from 'lucide-react';
import {chapters,lessons} from './course';
import {adcSample,channelValue,defaultRadio,encodeText,pamAlphabet,quantize,receiveMessage,shapedValue,type EncodedMessage,type RadioSettings} from './transmission';

const stages=[
 {title:'Your message',subtitle:'An idea, still in text',kind:'Data',icon:Type,lesson:'digital-radio',book:'§1.2 · pp. 3–4',page:3,question:'What changes when a character becomes a number?'},
 {title:'Encode the bits',subtitle:'Characters → bytes → 0s & 1s',kind:'Software',icon:GitBranch,lesson:'digital-radio',book:'§1.2 · p. 4',page:4,question:'Write H as a character, a hex byte, and eight bits.'},
 {title:'Make PAM pulses',subtitle:'Bit pairs → pulse amplitudes',kind:'DSP / software',icon:Waves,lesson:'digital-radio',book:'§1.2 · pp. 4–5',page:4,question:'How do the pairs 00, 01, 10, and 11 become four amplitudes?'},
 {title:'DAC',subtitle:'Digital samples → voltage',kind:'Hardware',icon:CircuitBoard,lesson:'software-radio',book:'§1.2 · pp. 5–7',page:5,question:'What is discrete before the DAC, and what is continuous after it?'},
 {title:'RF + antenna',subtitle:'Baseband → radio frequency',kind:'Hardware',icon:Antenna,lesson:'mixers',book:'§1.2 · pp. 5–7; §3.6',page:5,question:'What does multiplying by a carrier change? What does the antenna do?'},
 {title:'Across the air',subtitle:'An electromagnetic field',kind:'Physical channel',icon:Radio,lesson:'channel-noise',book:'§1.2 · pp. 7–8',page:7,question:'Are actual zeros and ones flying through the air? Explain what is.'},
 {title:'Receive RF',subtitle:'Antenna → analog baseband',kind:'Hardware',icon:Antenna,lesson:'software-radio',book:'§1.2 · pp. 8–9; §3.6',page:8,question:'Why select, amplify, and translate the received signal before digitizing it?'},
 {title:'ADC',subtitle:'Sample time. Quantize voltage.',kind:'Hardware',icon:CircuitBoard,lesson:'sampling',book:'§1.2 · pp. 8–9; §3.4',page:8,question:'Sampling chooses when. Quantization chooses which amplitude code. Explain both.'},
 {title:'DSP decisions',subtitle:'Samples → estimated symbols',kind:'DSP / software',icon:Cpu,lesson:'software-radio',book:'§1.2 · pp. 9–12',page:9,question:'How is the ADC amplitude code different from the original message bits?'},
 {title:'Read the message',subtitle:'Symbols → bits → text',kind:'Data',icon:CheckCircle2,lesson:'digital-radio',book:'§1.2 · pp. 4–12',page:4,question:'Which assumptions let the receiver reverse the transmitter’s transformations?'}
];
const centers=[{x:110,y:70},{x:330,y:70},{x:550,y:70},{x:550,y:185},{x:330,y:185},{x:110,y:185},{x:110,y:300},{x:330,y:300},{x:550,y:300},{x:550,y:415}];
const fmt=(n:number,d=2)=>Number(n.toFixed(d)).toString();
const hex=(n:number)=>n.toString(16).padStart(2,'0').toUpperCase();
type Props={onOpenLesson:(id:string)=>void;onOpenBook:(page:number)=>void;onSaveNote:(id:string,text:string)=>void};
type Point={x:number;y:number};
type Series={label:string;points:Point[];color?:string;dots?:boolean;dashed?:boolean;step?:boolean};

function Trace({title,series,start,end,rate=1,selected,markers,cursor,yLimit=4.5,onPick}:{title:string;series:Series[];start:number;end:number;rate?:number;selected?:number;markers?:number[];cursor?:number;yLimit?:number;onPick?:(index:number)=>void}){
 const width=800,height=205,left=43,right=784,top=17,bottom=164;
 const sx=(x:number)=>left+(x-start)/(end-start)*(right-left),sy=(y:number)=>bottom-(y+yLimit)/(2*yLimit)*(bottom-top);
 const path=(points:Point[],step=false)=>points.map((p,i)=>`${i?(step?`H${sx(p.x).toFixed(2)}V`:'L'):'M'}${i&&step?'':sx(p.x).toFixed(2)+','}${sy(p.y).toFixed(2)}`).join(' ');
 return <section className="journey-trace"><div className="trace-heading"><h4>{title}</h4><div>{series.map((s,i)=><span key={s.label}><i style={{background:s.color||['var(--wave-1)','var(--wave-2)','var(--wave-3)'][i%3]}}/>{s.label}</span>)}</div></div><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={title}><title>{title}</title><defs><clipPath id={'trace-clip-'+title.replace(/\W/g,'')}><rect x={left} y={top} width={right-left} height={bottom-top}/></clipPath></defs>{[-4,-2,0,2,4].filter(v=>Math.abs(v)<=yLimit).map(v=><g key={v}><line x1={left} x2={right} y1={sy(v)} y2={sy(v)} stroke={v===0?'var(--axis)':'var(--grid)'} strokeDasharray={v===0?'':'3 4'}/><text x={left-10} y={sy(v)+4} textAnchor="end">{v}</text></g>)}{Array.from({length:5},(_,i)=>{const x=start+(end-start)*i/4;return <g key={i}><text x={sx(x)} y={185} textAnchor="middle">{fmt(x/rate,3)}</text></g>})}<g clipPath={`url(#trace-clip-${title.replace(/\W/g,'')})`}>{selected!==undefined&&<rect x={sx(selected)} y={top} width={sx(selected+1)-sx(selected)} height={bottom-top} fill="var(--selection)"/>}{markers?.map((m,i)=><line key={i} x1={sx(m)} x2={sx(m)} y1={top} y2={bottom} stroke="#ffc18a66" strokeDasharray="3 4"/>)}{series.map((s,i)=><g key={s.label}>{s.dots?s.points.map((p,j)=><circle key={j} cx={sx(p.x)} cy={sy(p.y)} r={onPick?4:3} fill={s.color||'var(--wave-2)'} tabIndex={onPick?0:undefined} role={onPick?'button':undefined} aria-label={onPick?`Inspect sample ${j+1}, ${fmt(p.y,3)} volts`:undefined} onClick={()=>onPick?.(j)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onPick?.(j)}}}><title>{fmt(p.x/rate,4)} s: {fmt(p.y,4)} V</title></circle>):<path d={path(s.points,s.step)} fill="none" stroke={s.color||['var(--wave-1)','var(--wave-2)','var(--wave-3)'][i%3]} strokeWidth={s.dashed?1.5:2.1} strokeDasharray={s.dashed?'5 4':undefined}/>}</g>)}</g>{cursor!==undefined&&<g><line x1={sx(cursor)} x2={sx(cursor)} y1={top} y2={bottom} stroke="var(--wave-1)" strokeWidth="1.2" opacity=".7"/><circle cx={sx(cursor)} cy={top} r="3" fill="var(--wave-1)"/><text x={Math.min(sx(cursor)+6,right-70)} y={top-5} style={{fill:'var(--wave-1)'}}>t = {fmt(cursor/rate,3)} s</text></g>}<text x="11" y="28">V</text><text x={(left+right)/2} y="203" textAnchor="middle">time (seconds) · slow-motion example</text></svg></section>;
}
function Slider({label,value,min,max,step=1,unit='',onChange}:{label:string;value:number;min:number;max:number;step?:number;unit?:string;onChange:(n:number)=>void}){return <label className="journey-slider"><span>{label}<output>{fmt(value,3)}{unit&&' '+unit}</output></span><input type="range" aria-label={label} value={value} min={min} max={max} step={step} onChange={e=>onChange(+e.target.value)}/></label>}
function Hardware({blocks}:{blocks:{name:string;detail:string;type?:string}[]}){return <div className="hardware-chain">{blocks.map((b,i)=><div className="hardware-step" key={b.name}><span>{i+1}</span><strong>{b.name}</strong><small>{b.detail}</small>{i<blocks.length-1&&<ArrowRight size={15}/>}</div>)}</div>}
function BitRow({bits,active,onSelect}:{bits:string;active?:number;onSelect?:(i:number)=>void}){return <div className="bit-row">{Array.from({length:bits.length/2},(_,i)=><button key={i} className={'bit-pair '+(active===i?'active':'')} onClick={()=>onSelect?.(i)} disabled={!onSelect} aria-label={`Pair ${i+1}: ${bits.slice(2*i,2*i+2)}`}><span>{bits[2*i]}</span><span>{bits[2*i+1]}</span></button>)}</div>}

function LogicWave({bits,rate,firstByte}:{bits:string;rate:number;firstByte:number}){
 const shown=bits.slice(firstByte*8,firstByte*8+16),dx=744/Math.max(shown.length,1),y=(b:string)=>b==='1'?35:83;
 const path=Array.from(shown).map((b,i)=>`${i?'V'+y(b):'M32,'+y(b)}H${32+(i+1)*dx}${i<shown.length-1?'H'+(32+(i+1)*dx):''}`).join(' ');
 return <div className="logic-wave"><h4>The bitstream, drawn as logic levels</h4><svg viewBox="0 0 800 120" role="img" aria-label="A square-wave logic view of the selected message bits"><title>Binary logic levels before PAM grouping</title><text x="12" y="39">1</text><text x="12" y="87">0</text><path d="M32 35H776M32 83H776" fill="none" stroke="var(--grid)" strokeDasharray="3 4"/>{Array.from(shown).map((b,i)=><g key={i}><line x1={32+i*dx} x2={32+i*dx} y1="24" y2="94" stroke="var(--line)"/><text x={32+(i+.5)*dx} y="17" textAnchor="middle">{b}</text><text x={32+(i+.5)*dx} y="112" textAnchor="middle">{firstByte*8+i+1}</text></g>)}<path d={path} fill="none" stroke="var(--wave-1)" strokeWidth="2"/></svg><p>Each horizontal interval is one bit ({fmt(1/(2*rate),3)} s at {2*rate} bit/s). This is a logic-level drawing. Our radio groups two of these bits into one four-level PAM symbol; it does not transmit these 0/1 labels directly.</p></div>;
}

function Encoding({encoded,byte,onByte,onSymbol}:{encoded:EncodedMessage;byte:number;onByte:(n:number)=>void;onSymbol:(n:number)=>void}){
 const value=encoded.bytes[byte],char=encoded.characters.find(c=>byte>=c.byteOffset&&byte<c.byteOffset+c.bytes.length);
 return <><div className="character-cards">{encoded.characters.map((c,i)=><button key={i} className={byte>=c.byteOffset&&byte<c.byteOffset+c.bytes.length?'active':''} onClick={()=>onByte(c.byteOffset)}><strong>{c.character===' '?'␣':c.character}</strong><span>{c.bytes.map(hex).join(' ')}</span><small>{c.bytes.length} {c.bytes.length===1?'byte':'bytes'}</small></button>)}{!encoded.bytes.length&&<p>Type a message above to unfold its bytes here.</p>}</div>{value!==undefined&&<div className="byte-explainer"><div className="byte-identity"><span className="lab-kicker">SELECTED CHARACTER</span><strong>{char?.character===' '?'space':char?.character}</strong><span>Unicode U+{char?.character.codePointAt(0)?.toString(16).toUpperCase().padStart(4,'0')}</span>{char&&char.bytes.length>1&&<div className="byte-choices">{char.bytes.map((b,i)=><button className={byte===char.byteOffset+i?'active':''} key={i} onClick={()=>onByte(char.byteOffset+i)}>Byte {i+1}: {hex(b)}</button>)}</div>}</div><div className="byte-transform"><div><span>Decimal byte value</span><strong>{value}</strong></div><ArrowRight size={17}/><div><span>Hexadecimal</span><strong>0x{hex(value)}</strong></div><ArrowRight size={17}/><div className="binary-byte"><span>Binary · 8 bits</span><BitRow bits={value.toString(2).padStart(8,'0')} onSelect={i=>onSymbol(byte*4+i)}/></div></div></div>}<div className="explain-strip"><GitBranch size={18}/><p><strong>Same information, different representations.</strong> A hex digit represents four bits. Two hex digits represent one byte. These characters use UTF-8; ASCII characters such as H use one byte, while é uses two and many emoji use four. The radio carries the bytes, not the written glyph.</p></div></>;
}
function FieldWave({encoded,settings,phase}:{encoded:EncodedMessage;settings:RadioSettings;phase:number}){
 const count=Math.max(1,Math.min(encoded.symbols.length,5)),points=Array.from({length:361},(_,i)=>{
  const z=i/360*count,u=((z-phase)%count+count)%count,a=settings.gain*shapedValue(encoded.symbols,u,settings.pulse)/3;
  const field=a*Math.cos(2*Math.PI*settings.carrierCycles*u);return{x:80+i/360*650,e:125-field*53,h:125+field*30,dx:field*18};
 });
 return <div className="em-scene"><svg viewBox="0 0 810 250" role="img" aria-label="Electromagnetic wave: electric and magnetic fields are perpendicular to the direction of propagation"><defs><marker id="field-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10" fill="var(--axis)"/></marker></defs><path d="M50 125H764" stroke="var(--axis)" markerEnd="url(#field-arrow)"/><path d="M80 190V45M45 85L135 190" stroke="var(--axis)"/><text x="71" y="33" fill="var(--wave-1)">E</text><text x="143" y="202" fill="var(--wave-2)">H</text><text x="567" y="226">direction of travel →</text>{points.filter((_,i)=>i%6===0).map((p,i)=><g key={i}><line x1={p.x} y1="125" x2={p.x} y2={p.e} stroke="#c4b5fd40"/><line x1={p.x} y1="125" x2={p.x+p.dx} y2={p.h} stroke="#ffc18a44"/></g>)}<path d={points.map((p,i)=>`${i?'L':'M'}${p.x},${p.e}`).join(' ')} fill="none" stroke="var(--wave-1)" strokeWidth="2"/><path d={points.map((p,i)=>`${i?'L':'M'}${p.x+p.dx},${p.h}`).join(' ')} fill="none" stroke="var(--wave-2)" strokeWidth="2"/><text x="485" y="36" fill="var(--wave-1)">Electric field E</text><text x="485" y="55" fill="var(--wave-2)">Magnetic field H</text></svg><p>The field amplitudes follow your PAM message. E and H are perpendicular to each other and to propagation; this perspective drawing is schematic and the scales differ.</p></div>;
}

function MiniScope({kind,encoded,received,settings,start,phase,moving}:{kind:number;encoded:EncodedMessage;received:ReturnType<typeof receiveMessage>;settings:RadioSettings;start:number;phase:number;moving:boolean}){
 const end=Math.max(start+1,Math.min(encoded.symbols.length,start+4)),span=end-start,w=500,l=35,r=483,t=20,b=160;
 const sx=(u:number)=>l+(u-start)/span*(r-l),sy=(v:number)=>b-(v+4.5)/9*(b-t);
 const pts=Array.from({length:481},(_,i)=>{const x=start+span*i/480;return{x,base:shapedValue(encoded.symbols,x,settings.pulse),rx:channelValue(encoded.symbols,x,settings)}});
 const path=(points:Point[],step=false)=>points.map((p,i)=>i?(step?`H${sx(p.x)}V${sy(p.y)}`:`L${sx(p.x)},${sy(p.y)}`):`M${sx(p.x)},${sy(p.y)}`).join(' ');
 const base=pts.map(p=>({x:p.x,y:p.base}));
 const line=kind===4?pts.map(p=>({x:p.x,y:p.base*Math.cos(2*Math.PI*settings.carrierCycles*p.x)})):kind===6?pts.map(p=>({x:p.x,y:p.rx})):kind>=7?pts.map(p=>({x:p.x,y:p.rx})):base;
 const samples=Array.from({length:span*settings.samplesPerSymbol},(_,i)=>adcSample(encoded.symbols,start*settings.samplesPerSymbol+i,settings));
 const title=kind===2?'PAM pulse amplitudes':kind===3?'DAC hold and target voltage':kind===4?'Your message on a carrier':kind===6?'Recovered analog baseband':kind===7?'Analog voltage and ADC measurements':'Digital symbol decisions';
 return <div className="mini-scope"><div className="mini-scope-label"><strong>{title}</strong><span>{kind===7?'dots = quantized samples':kind===8?'dots = corrected samples':'voltage / V'}</span></div><svg viewBox={`0 0 ${w} 207`} role="img" aria-label={title}><defs><clipPath id="mini-scope-clip"><rect x={l} y={t} width={r-l} height={b-t}/></clipPath></defs>{[-3,0,3].map(v=><g key={v}><line x1={l} x2={r} y1={sy(v)} y2={sy(v)} stroke="var(--grid)" strokeDasharray={v===0?undefined:'3 5'}/><text x={l-10} y={sy(v)+5} textAnchor="end">{v}</text></g>)}<g clipPath="url(#mini-scope-clip)">{kind===8? <>{[-2,2].map(v=><line key={v} x1={l} x2={r} y1={sy(v)} y2={sy(v)} stroke="var(--wave-2)" strokeDasharray="5 5" opacity=".5"/>)}{received.decisions.slice(start,end).map((d,i)=><g key={i}><circle cx={sx(d.u)} cy={sy(d.original)} r="5" fill="none" stroke="var(--wave-3)"/><circle cx={sx(d.u)} cy={sy(d.corrected)} r="3.5" fill={d.error?'var(--wave-2)':'var(--wave-1)'}/></g>)}</>:<><path d={path(line)} fill="none" stroke="var(--wave-1)" strokeWidth="2.4"/>{kind===3&&<path d={path(Array.from({length:span*32+1},(_,i)=>{const x=start+i/32;return{x,y:shapedValue(encoded.symbols,x,settings.pulse)}}),true)} fill="none" stroke="var(--wave-2)" strokeWidth="1.4" opacity=".85"/>}{kind===4&&<path d={path(base)} fill="none" stroke="var(--wave-2)" strokeWidth="1.4" strokeDasharray="4 4"/>}{kind===7&&samples.map(p=><g key={p.index}><line x1={sx(p.u)} x2={sx(p.u)} y1={sy(0)} y2={sy(p.value)} stroke="var(--wave-2)" opacity=".25"/><circle cx={sx(p.u)} cy={sy(p.value)} r="3" fill="var(--wave-2)"/></g>)}</>}{moving&&<line x1={l+phase*(r-l)} x2={l+phase*(r-l)} y1={t} y2={b} stroke="#f0ddff" strokeWidth="1.3"/>}</g>{Array.from({length:5},(_,i)=><text key={i} x={l+i/4*(r-l)} y="185" textAnchor={i===0?'start':i===4?'end':'middle'}>{fmt((start+span*i/4)/settings.symbolRate,3)} s</text>)}</svg><p>Symbols {start+1}–{end} of {encoded.symbols.length} · {settings.symbolRate} symbols/s</p></div>;
}

function LiveSignalPanel({index,encoded,received,settings,byte,symbol,phase,moving,playing,animating,onPause,onPlay,onSettings,onAnimate,onExplore,onByte,onStage}:{index:number;encoded:EncodedMessage;received:ReturnType<typeof receiveMessage>;settings:RadioSettings;byte:number;symbol:number;phase:number;moving:boolean;playing:boolean;animating:boolean;onPause:()=>void;onPlay:()=>void;onSettings:(s:Partial<RadioSettings>)=>void;onAnimate:()=>void;onExplore:()=>void;onByte:(n:number)=>void;onStage:(n:number)=>void}){
 const stage=stages[index],Icon=stage.icon,start=Math.floor(symbol/4)*4,selectedByte=Math.min(encoded.bytes.length-1,playing?Math.floor(phase*encoded.bytes.length):byte),value=encoded.bytes[selectedByte];
 const n=Math.min(Math.max(0,encoded.symbols.length*settings.samplesPerSymbol-1),Math.floor((start+phase*Math.min(4,Math.max(1,encoded.symbols.length-start)))*settings.samplesPerSymbol));
 const sample=adcSample(encoded.symbols,n,settings),decision=received.decisions[Math.min(received.decisions.length-1,start+Math.floor(phase*4))];
 const copy=[
  'Your text becomes byte values. Click a character to inspect its representation.',
  'One byte has eight bits. A hexadecimal digit represents four bits; the radio groups adjacent bits into pairs.',
  'Each bit pair selects a pulse height. The symbol interval stays fixed while the amplitude carries information.',
  'A DAC converts numerical samples into a physical voltage. The orange line is held output; purple is the ideal target.',
  'The RF front end mixes baseband with a carrier, filters and amplifies it, then drives an antenna.',
  'The antenna launches changing electric and magnetic fields. Their modulation carries your message through space.',
  'An antenna senses a voltage. RF hardware selects, amplifies, and shifts it back toward baseband.',
  'Sampling chooses when to measure. Quantization assigns an amplitude code. That code is different from your message bits.',
  'DSP uses the ADC numbers to estimate PAM levels, then reverses the symbol-to-bit mapping.',
  'The receiver turns its decided bit pairs back into bytes, then decodes the text. Change the channel and watch the result.'
 ][index];
 return <aside className="live-signal-panel" aria-label="Live signal illustration" onPointerDown={e=>{if(!(e.target as Element).closest('[data-playback]'))onPause()}} onFocusCapture={e=>{if(!(e.target as Element).closest('[data-playback]'))onPause()}} onWheel={onPause}><div className="live-panel-top"><span><i className={moving?'moving':''}/>LIVE SIGNAL VIEW</span><button data-playback="true" onClick={playing?onPause:onPlay} disabled={!encoded.bytes.length}>{playing?<Pause size={14}/>:<Play size={14}/>} {playing?'Hold this step':'Continue journey'}</button></div><div className="live-stage-title"><span><Icon size={22}/></span><div><label className="live-stage-picker"><select aria-label="Live signal step" value={index} onChange={e=>onStage(+e.target.value)}>{stages.map((s,i)=><option key={s.title} value={i}>{String(i+1).padStart(2,'0')} / 10 · {s.title}</option>)}</select></label><h2>{stage.title}</h2></div></div>
  {index===0&&<div className="live-message"><span className="lab-kicker">TEXT → ENCODED BYTES</span><div>{encoded.characters.map((c,i)=><button key={i} className={selectedByte>=c.byteOffset&&selectedByte<c.byteOffset+c.bytes.length?'active':''} onClick={()=>onByte(c.byteOffset)}><strong>{c.character===' '?'␣':c.character}</strong><small>{c.bytes.map(hex).join(' ')}</small></button>)}</div><p>{encoded.bytes.length} bytes × 8 = <strong>{encoded.bits.length} bits</strong></p></div>}
  {index<=1&&value!==undefined&&<div className="live-byte"><span>BYTE {selectedByte+1}</span><strong>0x{hex(value)}</strong><ArrowRight size={17}/><code>{value.toString(2).padStart(8,'0').replace(/(.{2})/g,'$1 ').trim()}</code></div>}
  {index===1&&value!==undefined&&<LogicWave bits={encoded.bits} rate={settings.symbolRate} firstByte={selectedByte}/>}
  {[2,3,4,6,7,8].includes(index)&&<MiniScope kind={index} encoded={encoded} received={received} settings={settings} start={start} phase={phase} moving={moving}/>}
  {index===2&&<div className="live-pam-legend">{pamAlphabet.map(p=><span key={p.bits}><code>{p.bits}</code><ArrowRight size={12}/><strong>{p.level>0?'+':''}{p.level}</strong></span>)}</div>}
  {index===3&&<div className="live-hardware"><Cpu size={21}/><span>numbers</span><ArrowRight size={14}/><CircuitBoard size={23}/><span>DAC</span><ArrowRight size={14}/><Waves size={24}/><span>voltage</span></div>}
  {(index===4||index===6)&&<div className="live-hardware"><span>{index===4?'Mixer':'Antenna'}</span><ArrowRight size={14}/><span>{index===4?'Filter + amp':'Filter + LNA'}</span><ArrowRight size={14}/><span>{index===4?'Antenna':'Mixer + LPF'}</span><Antenna size={24}/></div>}
  {index===5&&<div className="live-field"><FieldWave encoded={encoded} settings={settings} phase={phase*4}/></div>}
  {index===7&&<><div className="live-sample"><span><small>MEASURED</small><strong>{fmt(sample.input,3)} V</strong></span><ArrowRight size={15}/><span><small>QUANTIZED</small><strong>{fmt(sample.value,3)} V</strong></span><ArrowRight size={15}/><span><small>ADC CODE</small><strong className="mono">{sample.binary}</strong></span></div><div className="live-controls"><Slider label="ADC resolution" min={1} max={8} value={settings.adcBits} unit="bits" onChange={v=>onSettings({adcBits:v})}/><label className="journey-select">Samples / symbol<select aria-label="Live ADC samples per symbol" value={settings.samplesPerSymbol} onChange={e=>onSettings({samplesPerSymbol:+e.target.value})}>{[4,8,16,32].map(v=><option key={v}>{v}</option>)}</select></label></div></>}
  {index===8&&decision&&<><div className="live-sample"><span><small>CORRECTED</small><strong>{fmt(decision.corrected,3)} V</strong></span><ArrowRight size={15}/><span><small>PAM LEVEL</small><strong>{decision.decided}</strong></span><ArrowRight size={15}/><span><small>MESSAGE BITS</small><strong className="mono">{decision.bits}</strong></span></div><label className="journey-checkbox live-gain"><input type="checkbox" checked={settings.correctGain} onChange={e=>onSettings({correctGain:e.target.checked})}/>Ideal gain compensation</label></>}
  {index===9&&<div className={'live-received '+(received.bitErrors?'errors':'')}><span className="lab-kicker">SENT</span><p>{encoded.characters.map(c=>c.character).join('')||'…'}</p><span className="lab-kicker">RECEIVED</span><p aria-live="polite">{received.text||'…'}</p><span>{received.bitErrors?`${received.bitErrors} of ${encoded.bits.length} bits changed`:'✓ Message recovered'}</span></div>}
  {(index===5||index===9)&&<div className="live-controls"><Slider label="Noise strength" min={0} max={1.5} step={.05} unit="V" value={settings.noise} onChange={v=>onSettings({noise:v})}/><Slider label="Channel gain" min={.25} max={1.5} step={.05} value={settings.gain} onChange={v=>onSettings({gain:v})}/></div>}
  <p className="live-explanation">{copy}</p><div className="live-panel-actions">{index>=2&&index<=8&&<button onClick={onAnimate}><Waves size={15}/>{animating?'Freeze waveform':'Animate signal'}</button>}<button onClick={onExplore}><BookOpen size={15}/>Explore this step<ChevronRight size={14}/></button></div><p className="live-pause-hint">Click a node, adjust a control, or scroll here to pause. Resume when you’re ready.</p>
 </aside>;
}

export default function SignalJourney({onOpenLesson,onOpenBook,onSaveNote}:Props){
 const [message,setMessage]=useState('Hello'),[settings,setSettings]=useState<RadioSettings>(defaultRadio),[playhead,setPlayhead]=useState(0),[playing,setPlaying]=useState(false),[speed,setSpeed]=useState(.5),[byte,setByte]=useState(0),[symbol,setSymbol]=useState(0),[adcTab,setAdcTab]=useState('sample'),[samplePick,setSamplePick]=useState(0),[scopeRunning,setScopeRunning]=useState(false),[scopeTime,setScopeTime]=useState(0),[zoom,setZoom]=useState(1),[drafts,setDrafts]=useState<Record<number,string>>({}),[exploring,setExploring]=useState(false);
 const mapRef=useRef<HTMLDivElement>(null),inspectorRef=useRef<HTMLElement>(null),encoded=useMemo(()=>encodeText(message),[message]),received=useMemo(()=>receiveMessage(encoded,settings),[encoded,settings]);
 const index=Math.min(stages.length-1,Math.floor(playhead)),stage=stages[index],Icon=stage.icon;
 useEffect(()=>{if(!playing)return;const id=setInterval(()=>setPlayhead(p=>Math.min(9.999,p+.04*speed)),80);return()=>clearInterval(id)},[playing,speed]);
 useEffect(()=>{if(playhead>=9.999)setPlaying(false)},[playhead]);
 useEffect(()=>{if(!scopeRunning||index<2||index>8)return;const id=setInterval(()=>setScopeTime(t=>t+.015),60);return()=>clearInterval(id)},[scopeRunning,index]);
 useEffect(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)setSpeed(.5)},[]);
 const set=(patch:Partial<RadioSettings>)=>{setPlaying(false);setSettings(s=>({...s,...patch}))};
 const choose=(i:number,_inspect=false)=>{setPlayhead(i);setPlaying(false)};
 const explore=()=>{setPlaying(false);setExploring(true);requestAnimationFrame(()=>inspectorRef.current?.scrollIntoView({behavior:'smooth',block:'start'}))};
 useEffect(()=>{if(playing)setExploring(false)},[playing]);
 const selectSymbol=(i:number)=>{setSymbol(i);setByte(Math.floor(i/4))};
 const start=()=>{if(!encoded.bytes.length)return;setPlayhead(0);setPlaying(true)};
 const activeSymbol=Math.max(0,Math.min(symbol,encoded.symbols.length-1)),windowStart=Math.floor(activeSymbol/8)*8,windowEnd=Math.max(windowStart+1,Math.min(encoded.symbols.length,windowStart+8));
 const baseTrace=useMemo(()=>Array.from({length:801},(_,i)=>{const x=windowStart+(windowEnd-windowStart)*i/800;return{x,y:shapedValue(encoded.symbols,x,settings.pulse)}}),[encoded,settings.pulse,windowStart,windowEnd]);
 const receivedTrace=useMemo(()=>baseTrace.map(p=>({x:p.x,y:channelValue(encoded.symbols,p.x,settings)})),[baseTrace,encoded,settings]);
 const rfTrace=useMemo(()=>baseTrace.map(p=>({x:p.x,y:p.y*Math.cos(2*Math.PI*settings.carrierCycles*p.x)})),[baseTrace,settings.carrierCycles]);
 const samples=useMemo(()=>Array.from({length:Math.max(1,(windowEnd-windowStart)*settings.samplesPerSymbol)},(_,i)=>adcSample(encoded.symbols,windowStart*settings.samplesPerSymbol+i,settings)),[encoded,settings,windowStart,windowEnd]);
 const pickedIndex=scopeRunning?Math.floor((scopeTime%1)*(samples.length-1)):Math.min(samplePick,samples.length-1),sample=samples[pickedIndex],cursor=scopeRunning?windowStart+(scopeTime%1)*(windowEnd-windowStart):undefined,decision=received.decisions[activeSymbol];
 const snippets=[message||'Your idea…',encoded.bits.slice(0,8)||'00000000',encoded.symbols.slice(0,4).map(n=>n>0?'+'+n:n).join('  ')||'−3  −1  +1  +3','numbers → volts',fmt(settings.carrierCycles*settings.symbolRate)+' Hz carrier','E ⟂ H ⟂ travel','select · amplify · mix',settings.adcBits+'-bit amplitude codes','levels → bit pairs',received.text||'Your idea…'];
 const empty=!encoded.bytes.length;
 const summary=<div className="transmission-facts"><span><strong>{encoded.characters.length}</strong> characters</span><span><strong>{encoded.bytes.length}</strong> bytes</span><span><strong>{encoded.bits.length}</strong> bits</span><span><strong>{encoded.symbols.length}</strong> 4-PAM symbols</span><span><strong>{fmt(encoded.symbols.length/settings.symbolRate)}</strong> seconds</span></div>;
 return <div className="signal-journey">
  <section className="journey-intro"><div><span className="lab-kicker"><span className="lab-live-dot"/> LECTURE 00 · THE BIG PICTURE, IN MOTION</span><h1>What happens<br/>after <em>“Hello”?</em></h1><p>Follow your message from an idea to a radio wave.<br/>Touch any step. See what changes. Make it click.</p></div><form className="message-composer" onSubmit={e=>{e.preventDefault();start()}}><label htmlFor="transmit-message">YOUR MESSAGE</label><div><input id="transmit-message" autoComplete="off" spellCheck={false} aria-label="Message to transmit" placeholder="Type something…" value={message} onChange={e=>{setMessage(Array.from(e.target.value).slice(0,24).join(''));setByte(0);setSymbol(0);setSamplePick(0);setPlaying(false);setPlayhead(0)}}/><button type="submit" disabled={empty} aria-label="Transmit your message"><Send size={21}/></button></div><p>Try <button type="button" onClick={()=>{setMessage('Hello');setByte(0);setSymbol(0);choose(0)}}>Hello</button>, your name, or <button type="button" onClick={()=>{setMessage('Hi 🌊');setByte(0);setSymbol(0);choose(0)}}>an emoji</button>. Up to 24 characters.</p>{summary}</form></section>

  <div className="journey-stage-layout"><section className={'signal-map '+(playing?'is-playing':'')} aria-label="Interactive transmitter and receiver map"><div className="map-toolbar"><div><GitBranch size={17}/><strong>The signal journey</strong><span>Click a node to look inside</span></div><div className="map-zoom"><button aria-label="Zoom out of signal map" onClick={()=>setZoom(z=>Math.max(.7,z-.1))}><ZoomOut size={16}/></button><button aria-label="Fit signal map" onClick={()=>setZoom(Math.min(1,(mapRef.current?.clientWidth||660)/660))}><Expand size={16}/></button><button aria-label="Zoom into signal map" onClick={()=>setZoom(z=>Math.min(1.3,z+.1))}><ZoomIn size={16}/></button></div></div><div className="map-viewport" ref={mapRef}><div className="map-space" style={{width:660*zoom,height:480*zoom}}><div className="map-inner" style={{transform:`scale(${zoom})`}}><svg className="map-wires" viewBox="0 0 660 480" aria-hidden="true"><defs><marker id="map-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10" fill="var(--map-wire)"/></marker></defs>{centers.slice(0,-1).map((p,i)=>{const q=centers[i+1];return <path key={i} d={`M${p.x},${p.y}L${q.x},${q.y}`} stroke={i<index?'var(--green)':'var(--map-wire)'} strokeWidth={i<index?2.5:1.5} strokeDasharray={i<index?undefined:'4 5'} markerEnd="url(#map-arrow)"/>})}{index<9&&<circle cx={centers[index].x+(centers[index+1].x-centers[index].x)*(playhead%1)} cy={centers[index].y+(centers[index+1].y-centers[index].y)*(playhead%1)} r="5" fill="var(--wave-1)" stroke="white" strokeWidth="2"/>}</svg><span className="map-lane tx">TRANSMITTER <span>turn data into a physical signal</span></span><span className="map-lane rx">RECEIVER <span>recover data from measurements</span></span><div className="map-center-label"><span>DATA</span><ArrowRight size={13}/><span>VOLTAGE</span><ArrowRight size={13}/><Radio size={16}/><span>EM FIELD</span><ArrowRight size={13}/><span>VOLTAGE</span><ArrowRight size={13}/><span>DATA</span></div>{stages.map((s,i)=>{const NodeIcon=s.icon;return <button key={s.title} aria-pressed={index===i} aria-label={`Step ${i+1}: ${s.title}`} className={'signal-node '+(index===i?'active ':'')+(i<index?'visited ':'')+((s.kind==='Hardware')?'is-hardware':s.kind.includes('software')||s.kind==='Software'?'is-software':'')} style={{left:centers[i].x-89,top:centers[i].y-44}} onClick={()=>choose(i,true)}><span className="node-top"><span className="node-number">{String(i+1).padStart(2,'0')}</span><span>{s.kind}</span>{i<index?<Check size={13}/>:<NodeIcon size={15}/>}</span><strong>{s.title}</strong><span className="node-snippet">{snippets[i]}</span></button>})}</div></div></div><div className="journey-player"><div className="player-buttons"><button className="play-button" disabled={empty} onClick={()=>{if(playing)setPlaying(false);else if(playhead>=9.999)start();else setPlaying(true)}}>{playing?<Pause size={15}/>:<Play size={15}/>}<span>{playing?'Pause':'Play journey'}</span></button><button aria-label="Previous transmission step" disabled={index===0} onClick={()=>choose(index-1)}><SkipBack size={16}/></button><button aria-label="Next transmission step" disabled={index===9} onClick={()=>choose(index+1)}><SkipForward size={16}/></button><button aria-label="Restart transmission" onClick={()=>choose(0)}><RotateCcw size={15}/></button></div><div className="player-current"><span>{String(index+1).padStart(2,'0')} / 10</span><strong>{stage.title}</strong></div><label className="play-speed">Playback<select aria-label="Playback speed" value={speed} onChange={e=>setSpeed(+e.target.value)}><option value={.25}>0.25×</option><option value={.5}>0.5×</option><option value={1}>1×</option><option value={2}>2×</option></select></label></div></section>

  <LiveSignalPanel index={index} encoded={encoded} received={received} settings={settings} byte={byte} symbol={activeSymbol} phase={scopeRunning?scopeTime%1:playing?playhead%1:0} moving={playing||scopeRunning} playing={playing} animating={scopeRunning} onPause={()=>setPlaying(false)} onPlay={()=>{if(playhead>=9.999)start();else setPlaying(true)}} onSettings={set} onAnimate={()=>{setPlaying(false);setScopeRunning(s=>!s)}} onExplore={explore} onStage={choose} onByte={n=>{setPlaying(false);setByte(n);setSymbol(n*4)}}/></div>
  <details className="journey-deep-dive" open={exploring} onToggle={e=>{setExploring(e.currentTarget.open);if(e.currentTarget.open)setPlaying(false)}}><summary className="deep-dive-summary"><BookOpen size={17}/>Explore this step in detail <span>{stage.title}</span></summary><section className="journey-workbench" ref={inspectorRef} aria-label="Selected transmission step"><div className="inspector-toolbar"><button onClick={()=>mapRef.current?.closest('.signal-map')?.scrollIntoView({behavior:'smooth',block:'start'})}><GitBranch size={14}/>Back to map</button><div>{index>=2&&index<=8&&<button className="scope-toggle" onClick={()=>setScopeRunning(s=>!s)}><Waves size={14}/><span>{scopeRunning?'Pause waveform':'Animate signal'}</span></button>}<button aria-label="Previous inspector step" disabled={index===0} onClick={()=>choose(index-1)}><SkipBack size={15}/></button><button aria-label={playing?'Pause inspection playback':'Play from this step'} disabled={empty} onClick={()=>{if(playing)setPlaying(false);else if(playhead>=9.999)start();else setPlaying(true)}}>{playing?<Pause size={15}/>:<Play size={15}/>}</button><button aria-label="Next inspector step" disabled={index===9} onClick={()=>choose(index+1)}><SkipForward size={15}/></button></div></div><div className="stage-heading"><span className="stage-icon"><Icon size={23}/></span><div><span className="lab-kicker">STEP {String(index+1).padStart(2,'0')} · {stage.kind.toUpperCase()}</span><h2>{stage.title}</h2><p>{stage.subtitle}</p></div><button className="lesson-shortcut" onClick={()=>onOpenLesson(stage.lesson)}>Related lecture<ArrowUpRight size={15}/></button></div>
   {index<=1&&<><p className="stage-lead">{index===0?'A computer stores a message as numbers. Click a character to unfold its actual byte values.':'Encoding gives each byte eight bits. Read them from left to right; the transmitter then groups those bits into pairs for 4-PAM.'}</p><Encoding encoded={encoded} byte={byte} onByte={n=>{setByte(n);setSymbol(n*4)}} onSymbol={i=>{selectSymbol(i);choose(2)}}/>{index===1&&<div className="byte-stream"><span className="lab-kicker">THE COMPLETE BYTE STREAM · CLICK A BYTE</span><div>{encoded.bytes.map((b,i)=><button className={i===byte?'active':''} key={i} onClick={()=>{setByte(i);setSymbol(i*4)}}><small>BYTE {i+1} · 0x{hex(b)}</small><strong>{b.toString(2).padStart(8,'0')}</strong></button>)}</div></div>}{index===1&&encoded.bytes.length>0&&<LogicWave bits={encoded.bits} rate={settings.symbolRate} firstByte={byte}/>}{index===1&&<p className="plot-footnote">Bit positions run left to right. The next step groups adjacent bits into pairs, so its pulse interval is twice the bit interval.</p>}<div className="try-next"><span><strong>Predict it:</strong> How many symbols does {encoded.bits.length||40} bits need if each symbol carries two bits?</span><button onClick={()=>choose(2)}>See the PAM mapping <ArrowRight size={15}/></button></div></>}

   {index===2&&<><p className="stage-lead">Pulse amplitude modulation (PAM) uses the height of a pulse to carry information. Here, every pair of bits selects one of four amplitudes.</p><div className="pam-alphabet">{pamAlphabet.map(p=><div className={encoded.bits.slice(activeSymbol*2,activeSymbol*2+2)===p.bits?'active':''} key={p.bits}><span>{p.bits}</span><ArrowRight size={15}/><strong>{p.level>0?'+':''}{p.level} V</strong><small>one symbol</small></div>)}</div><div className="symbol-ribbon"><span className="lab-kicker">YOUR MESSAGE · TWO BITS PER SYMBOL · CLICK TO INSPECT</span><div>{encoded.symbols.map((s,i)=><button className={activeSymbol===i?'active':''} key={i} onClick={()=>selectSymbol(i)}><span>{encoded.bits.slice(i*2,i*2+2)}</span><strong>{s>0?'+':''}{s}</strong><small>{i+1}</small></button>)}</div></div><div className="journey-control-row"><Slider label="Symbol rate" value={settings.symbolRate} min={1} max={10} unit="symbols/s" onChange={n=>set({symbolRate:n})}/><label className="journey-select">Pulse shape<select aria-label="Pulse shape" value={settings.pulse} onChange={e=>set({pulse:e.target.value as RadioSettings['pulse']})}><option value="rectangular">Rectangular · introductory model</option><option value="raised-cosine">Raised cosine · β = 0.35</option></select></label></div><Trace cursor={cursor} title="Your bit pairs become a waveform" series={[{label:settings.pulse==='rectangular'?'Rectangular PAM pulses':'Raised-cosine PAM',points:baseTrace}]} start={windowStart} end={windowEnd} rate={settings.symbolRate} selected={activeSymbol}/><div className="explain-strip"><Waves size={19}/><p><strong>{encoded.bits.length} bits ÷ 2 = {encoded.symbols.length} symbols.</strong> Each symbol lasts T = {fmt(1/settings.symbolRate,3)} s; the bit rate is {2*settings.symbolRate} bit/s. Equal consecutive symbols make a flat section. Rectangular pulses give a step waveform; shaped pulses overlap, yet raised-cosine pulses are zero at the other symbol centers.</p></div><p className="plot-footnote">Showing symbols {windowStart+1}–{windowEnd} of {encoded.symbols.length}. Select another symbol above to move the window. Pulse shaping controls bandwidth; PAM specifies the amplitude alphabet.</p></>}

   {index===3&&<><p className="stage-lead">Software can calculate a waveform, but a cable needs a physical voltage. A digital-to-analog converter (DAC) makes that bridge.</p><Hardware blocks={[{name:'DSP samples',detail:'A list of numbers'},{name:'DAC chip',detail:'Numbers set voltage levels'},{name:'Sample & hold',detail:'Holds between updates'},{name:'Reconstruction filter',detail:'Suppresses spectral images'}]}/><div className="journey-control-row"><label className="journey-select">Compare pulse shapes<select aria-label="DAC pulse shape" value={settings.pulse} onChange={e=>set({pulse:e.target.value as RadioSettings['pulse']})}><option value="rectangular">Rectangular pulses</option><option value="raised-cosine">Raised-cosine pulses</option></select></label><div className="little-fact"><strong>32</strong><span>DAC updates per symbol in this illustration</span></div></div><Trace cursor={cursor} title="Numbers become an analog voltage" series={[{label:'Held DAC output',color:'var(--wave-2)',points:Array.from({length:(windowEnd-windowStart)*32+1},(_,i)=>{const x=windowStart+i/32;return{x,y:shapedValue(encoded.symbols,x,settings.pulse)}}),step:true},{label:'Ideal target waveform',points:baseTrace}]} start={windowStart} end={windowEnd} rate={settings.symbolRate}/><div className="explain-strip"><CircuitBoard size={20}/><p><strong>“Digital” and “analog” describe the representation.</strong> Before the DAC: discrete numerical samples. After it: an electrical voltage that exists continuously in time. The staircase still exists at every instant, even while its value is held constant. Switch to raised cosine to see a smoother target waveform.</p></div><p className="plot-footnote">The blue curve is the ideal reconstruction target, not a simulated analog filter. Perfect rectangular pulses require unlimited bandwidth; real hardware rounds the transitions.</p></>}

   {index===4&&<><p className="stage-lead">The RF front end moves the baseband waveform to a carrier frequency, selects a band, and provides enough power for the antenna.</p><Hardware blocks={[{name:'Mixer',detail:'Multiply by an oscillator'},{name:'Band-pass filter',detail:'Select the wanted RF band'},{name:'Power amplifier',detail:'Drive the antenna'},{name:'Antenna',detail:'RF current → EM field'}]}/><div className="journey-control-row"><Slider label="Carrier cycles per symbol" value={settings.carrierCycles} min={3} max={12} onChange={n=>set({carrierCycles:n})}/><div className="little-fact"><strong>{settings.carrierCycles*settings.symbolRate} Hz</strong><span>slowed-down carrier · f꜀ = {settings.carrierCycles} Rₛ</span></div></div><Trace cursor={cursor} title="Baseband voltage" series={[{label:'Your PAM waveform',points:baseTrace}]} start={windowStart} end={windowEnd} rate={settings.symbolRate}/><Trace cursor={cursor} title="The same message at a carrier frequency" series={[{label:'PAM × cosine carrier',points:rfTrace}]} start={windowStart} end={windowEnd} rate={settings.symbolRate}/><div className="formula-note">sRF(t) = sBB(t) cos(2πf꜀t)</div><p className="plot-footnote">A negative PAM level reverses the carrier phase; it does not mean negative transmitted energy. The visible carrier is slowed down for learning. Practical radio carriers often operate at MHz or GHz.</p></>}

   {index===5&&<><p className="stage-lead">An antenna turns an alternating electrical current into a radiating electromagnetic field. At the other end, that field induces a small electrical signal in the receiving antenna.</p><FieldWave encoded={encoded} settings={settings} phase={scopeRunning?scopeTime:playing?playhead%1:0}/><div className="journey-control-row"><Slider label="Channel gain" value={settings.gain} min={.25} max={1.5} step={.05} onChange={n=>set({gain:n})}/><Slider label="Noise strength" value={settings.noise} min={0} max={1.5} step={.05} unit="V" onChange={n=>set({noise:n})}/><button className="small-action" onClick={()=>set({seed:settings.seed+1})}><RotateCcw size={14}/>New noise pattern</button></div><div className="explain-strip"><Radio size={21}/><p><strong>No tiny 0s and 1s are floating through the air.</strong> Changing electric and magnetic fields carry the modulation. The receiver measures a voltage and infers which symbols were sent. In free space, the wave propagates at approximately 3 × 10⁸ m/s.</p></div><Trace cursor={cursor} title="What the receiver must recover from" series={[{label:'Transmitted baseband',points:baseTrace,dashed:true},{label:'Received baseband equivalent',points:receivedTrace,color:'var(--wave-2)'}]} start={windowStart} end={windowEnd} rate={settings.symbolRate}/><div className="try-next"><span>Increase noise or reduce gain, then inspect the received message.</span><button onClick={()=>choose(9)}>Check the result <ArrowRight size={15}/></button></div></>}

   {index===6&&<><p className="stage-lead">The receiver’s RF front end prepares a weak analog signal for measurement. It selects the band, amplifies it, and shifts it down from RF to baseband (sometimes through an intermediate frequency).</p><Hardware blocks={[{name:'Antenna',detail:'EM field → voltage'},{name:'RF filter + LNA',detail:'Select and amplify'},{name:'Mixer + oscillator',detail:'Shift down in frequency'},{name:'Low-pass filter',detail:'Keep baseband; limit ADC input bandwidth'}]}/><Trace cursor={cursor} title="Mixing down creates a baseband term and a high-frequency image" series={[{label:'After coherent mixing',color:'var(--wave-2)',points:receivedTrace.map(p=>({x:p.x,y:p.y*(1+Math.cos(4*Math.PI*settings.carrierCycles*p.x))}))},{label:'Ideal low-pass output',points:receivedTrace}]} start={windowStart} end={windowEnd} rate={settings.symbolRate} yLimit={8}/><div className="formula-note">2 · [sBB(t) cos(2πf꜀t)] · cos(2πf꜀t) = sBB(t) + sBB(t) cos(4πf꜀t)</div><div className="explain-strip"><Antenna size={19}/><p><strong>The low-pass filter keeps the message term.</strong> The component around twice the carrier frequency is removed. This walkthrough assumes a correctly aligned carrier. Later lectures explain what happens when its frequency or phase is wrong.</p></div></>}

   {index===7&&<><p className="stage-lead">An analog-to-digital converter (ADC) does two different jobs: it samples the signal at chosen times and quantizes each measured amplitude into a finite binary code.</p><div className="adc-tabs" aria-label="ADC explanation">{[['sample','1. Sample time'],['quantize','2. Quantize voltage'],['codes','3. Store a binary code']].map(([id,label])=><button aria-pressed={adcTab===id} className={adcTab===id?'active':''} key={id} onClick={()=>setAdcTab(id)}>{label}</button>)}</div><div className="journey-control-row"><label className="journey-select">Samples per symbol<select aria-label="ADC samples per symbol" value={settings.samplesPerSymbol} onChange={e=>{set({samplesPerSymbol:+e.target.value});setSamplePick(0)}}>{[4,8,16,32].map(n=><option key={n} value={n}>{n} samples / symbol</option>)}</select></label><Slider label="ADC resolution" value={settings.adcBits} min={1} max={8} unit="bits/sample" onChange={n=>set({adcBits:n})}/><div className="little-fact"><strong>{settings.samplesPerSymbol*settings.symbolRate} samples/s</strong><span>fₛ = {settings.samplesPerSymbol} × Rₛ · Δt = {fmt(1/(settings.samplesPerSymbol*settings.symbolRate),4)} s</span></div></div>{adcTab==='sample'?<><Trace cursor={cursor} title="Sampling chooses when to measure" series={[{label:'Continuous analog voltage',points:receivedTrace},{label:'Samples',points:samples.map(p=>({x:p.u,y:p.input})),dots:true}]} start={windowStart} end={windowEnd} rate={settings.symbolRate} onPick={i=>{setScopeRunning(false);setSamplePick(i)}}/><div className="explain-strip"><CircuitBoard size={19}/><p><strong>The dots are discrete in time.</strong> Their amplitudes are still the unquantized measurement values in this view. Increasing the sample rate adds more measurement instants; it does not add more amplitude levels. Click a dot to inspect it below.</p></div></>:<><Trace cursor={cursor} title="Quantization replaces each measurement with an available level" series={[{label:'Analog input',points:receivedTrace,dashed:true},{label:'Quantized samples',points:samples.map(p=>({x:p.u,y:p.value})),dots:true,color:'var(--wave-2)'}]} start={windowStart} end={windowEnd} rate={settings.symbolRate} onPick={i=>{setScopeRunning(false);setSamplePick(i)}}/><div className="explain-strip"><Cpu size={19}/><p><strong>{settings.adcBits} bits → {2**settings.adcBits} amplitude bins.</strong> The ADC range is −4 to +4 V; bin width Δ = 8 / {2**settings.adcBits} = {fmt(8/2**settings.adcBits,4)} V. This is a uniform mid-rise quantizer: the reconstruction value sits at each bin’s center. More bits reduce its rounding error; they do not remove channel noise.</p></div></>}{sample&&<div className="sample-readout"><div><span>Sample n</span><strong>{sample.index}</strong></div><div><span>Time</span><strong>{fmt(sample.u/settings.symbolRate,4)} s</strong></div><div><span>Measured voltage</span><strong>{fmt(sample.input,4)} V</strong></div><ArrowRight size={17}/><div><span>Quantized value</span><strong>{fmt(sample.value,4)} V</strong></div><div><span>ADC output code</span><strong className="mono">{sample.binary}</strong></div><div><span>Quantization error</span><strong>{fmt(sample.value-sample.input,4)} V{sample.clipped?' · clipped':''}</strong></div></div>}{adcTab==='codes'&&<div className="sample-table-wrap"><table className="sample-table"><thead><tr><th>n</th><th>Time / s</th><th>Measured / V</th><th>Quantized / V</th><th>ADC code</th></tr></thead><tbody>{samples.slice(0,16).map((p,i)=><tr key={p.index} className={pickedIndex===i?'active':''} onClick={()=>setSamplePick(i)}><td><button aria-label={`Inspect ADC sample ${p.index}`} onClick={()=>setSamplePick(i)}>{p.index}</button></td><td>{fmt(p.u/settings.symbolRate,4)}</td><td>{fmt(p.input,3)}</td><td>{fmt(p.value,3)}</td><td className="mono">{p.binary}</td></tr>)}</tbody></table></div>}<p className="plot-footnote">The ADC code describes a measured amplitude; it is not the original text bit pair. For band-limited low-pass inputs, sample faster than twice the highest frequency. Ideal rectangular pulses are not band-limited; raised cosine is the band-limited reference here (tails are truncated for display).</p></>}

   {index===8&&<><p className="stage-lead">Digital signal processing (DSP) operates on the ADC’s numbers. With symbol timing and the carrier aligned, choose a measurement near each pulse center, correct its gain, and decide which of the four PAM levels was most likely.</p><div className="journey-control-row"><label className="journey-checkbox"><input type="checkbox" checked={settings.correctGain} onChange={e=>set({correctGain:e.target.checked})}/><span>Ideal gain compensation<small>divide by the selected channel gain</small></span></label><Slider label="Symbol timing offset" value={settings.timing} min={-.45} max={.45} step={.025} unit="T" onChange={n=>set({timing:n})}/><div className="little-fact"><strong>{received.symbolErrors}</strong><span>symbol decisions differ from the transmitter</span></div></div><Trace cursor={cursor} title="Choose a PAM symbol from each corrected measurement" series={[{label:'Original symbols',points:encoded.symbols.slice(windowStart,windowEnd).map((y,i)=>({x:windowStart+i+.5,y})),dashed:true},{label:'Corrected ADC measurements',points:received.decisions.slice(windowStart,windowEnd).map(p=>({x:p.u,y:p.corrected})),dots:true}]} start={windowStart} end={windowEnd} rate={settings.symbolRate} markers={received.decisions.slice(windowStart,windowEnd).map(p=>p.u)}/>{decision&&<div className="decision-card"><span className="lab-kicker">SYMBOL {activeSymbol+1} · DECISION THRESHOLDS: −2, 0, +2 V</span><div><span><small>ADC code</small><strong className="mono">{decision.binary}</strong></span><ArrowRight size={16}/><span><small>Corrected value</small><strong>{fmt(decision.corrected,3)} V</strong></span><ArrowRight size={16}/><span><small>Nearest PAM level</small><strong>{decision.decided>0?'+':''}{decision.decided}</strong></span><ArrowRight size={16}/><span><small>Recovered message bits</small><strong className="mono">{decision.bits}</strong></span></div></div>}<div className="decision-ribbon">{received.decisions.map((d,i)=><button key={i} className={(d.error?'error ':'')+(activeSymbol===i?'active':'')} onClick={()=>selectSymbol(i)}><small>#{i+1}</small><strong>{d.bits}</strong>{d.error?<span>changed</span>:<Check size={12}/>}</button>)}</div><div className="explain-strip"><Cpu size={19}/><p><strong>Hardware makes measurements. Software interprets them.</strong> Real receivers also filter, synchronize the carrier and symbol clock, estimate gain, and equalize echoes. Here the selected gain is known, and the timing slider lets you inspect decision timing. A DSP can run on a CPU, FPGA, or dedicated processor.</p></div></>}

   {index===9&&<><p className="stage-lead">The receiver reverses the mapping: decided PAM amplitudes become bit pairs, eight bits make a byte, and UTF-8 decoding turns bytes back into text.</p><div className={'message-result '+(received.bitErrors?'has-errors':'')}><div><span className="lab-kicker">YOU SENT</span><strong>{message||'…'}</strong></div><ArrowRight size={24}/><div><span className="lab-kicker">THE RECEIVER READS</span><strong aria-live="polite">{received.text||'…'}</strong></div><span className="result-badge">{received.bitErrors?<><Radio size={15}/>{received.bitErrors} bit errors</>:<><CheckCircle2 size={16}/>{empty?'Type a message to begin':'Message recovered'}</>}</span></div><div className="recovered-bytes">{encoded.bytes.map((b,i)=><div key={i} className={received.bytes[i]!==b?'error':''}><span>BYTE {i+1}</span><strong className="mono">{received.bits.slice(i*8,i*8+8)}</strong><small>0x{hex(received.bytes[i])}{received.bytes[i]!==b?' · sent 0x'+hex(b):' · matches'}</small></div>)}</div><div className="journey-control-row"><Slider label="Channel gain" value={settings.gain} min={.25} max={1.5} step={.05} onChange={n=>set({gain:n})}/><Slider label="Noise strength" value={settings.noise} min={0} max={1.5} step={.05} unit="V" onChange={n=>set({noise:n})}/><Slider label="ADC resolution" value={settings.adcBits} min={1} max={8} unit="bits/sample" onChange={n=>set({adcBits:n})}/></div><div className="try-next"><span><strong>Try to break it:</strong> increase noise, try a 1-bit ADC, or turn off gain compensation in DSP.</span><button onClick={()=>{setSettings(defaultRadio);choose(9)}}>Restore ideal conditions <RotateCcw size={14}/></button></div><p className="plot-footnote">{received.bitErrors} / {encoded.bits.length} bits changed. This link uses no error-correcting code. Invalid UTF-8 bytes can display as �. Both ends agree on the byte encoding and PAM mapping.</p></>}

   <div className="stage-study"><button onClick={()=>onOpenBook(stage.page)}><BookOpen size={16}/><span>Book {stage.book}</span><ArrowUpRight size={13}/></button><details className="stage-note" key={index}><summary><PenLine size={15}/>Make a note in your own words</summary><p>{stage.question}</p><textarea aria-label={`Your note about ${stage.title}`} maxLength={3000} placeholder="What clicked? Write your own explanation…" value={drafts[index]||''} onChange={e=>setDrafts(d=>({...d,[index]:e.target.value}))}/><button className="small-action" disabled={!drafts[index]?.trim()} onClick={()=>{onSaveNote(stage.lesson,stage.title+':\n'+drafts[index].trim());setDrafts(d=>({...d,[index]:''}))}}><Check size={14}/>Save to my notes</button></details></div>
  </section></details>
  <div className="journey-bottom"><button onClick={()=>choose(Math.max(0,index-1))} disabled={!index}><SkipBack size={15}/>Previous step</button><span>One message. Ten transformations. The same information.</span><button onClick={()=>choose(Math.min(9,index+1))} disabled={index===9}>Next step<ArrowRight size={15}/></button></div>
  <details className="model-assumptions"><summary>About this learning model</summary><p>This is a slow-motion, uncoded 4-PAM link using the book’s mapping: 00 → −3, 01 → −1, 10 → +1, 11 → +3. Rectangular pulses reproduce the introductory example. The raised-cosine reference has roll-off 0.35, with finite tails used for the drawing. RF mixing and the EM field are illustrative; reception uses an equivalent baseband signal with band-limited noise, ideal carrier recovery, and direct symbol-center decisions. The ADC is a uniform mid-rise quantizer over ±4 V. Timing selects the nearest actual ADC sample; optional gain correction uses the known channel gain. Framing, coding, multipath, equalization, a real RF filter response, and carrier errors are left for the related lecture experiments. DSP is an operation and may be implemented on several kinds of hardware.</p></details>
 </div>;
}

export function CourseMap({onNavigate,reviewed}:{onNavigate:(id:string)=>void;reviewed:Set<string>}){
 return <div className="course-mindmap"><div className="mindmap-intro"><span className="lab-kicker">ZOOM OUT · CONNECT THE IDEAS</span><h1>Everything <em>connects.</em></h1><p>Start with the whole radio. Follow a branch when you want to understand one piece.</p></div><button className="mindmap-hub" onClick={()=>onNavigate('home')}><span><Radio size={29}/></span><div><strong>Communication Systems</strong><small>Your message → the air → your message</small></div><ArrowUpRight size={20}/></button><div className="mindmap-branches">{chapters.map(ch=><section className={'mindmap-branch '+ch.color} key={ch.id}><header><span className="lab-kicker">LECTURE {String(ch.id).padStart(2,'0')}</span><h2>{ch.title}</h2><p>{ch.subtitle}</p></header><div className="mindmap-leaves">{lessons.filter(l=>l.chapter===ch.id).map(l=><button key={l.id} onClick={()=>onNavigate(l.id)}><span className={'leaf-dot '+(reviewed.has(l.id)?'reviewed':'')}>{reviewed.has(l.id)?<Check size={10}/>:null}</span><div><strong>{l.title}</strong><small>{l.subtitle}</small></div><ChevronRight size={15}/></button>)}</div><button className="branch-practice" onClick={()=>onNavigate(ch.id===2?'ex2':ch.id===1?'ps1':'home')}>{ch.id===0?'Trace your own message':ch.id===1?'Try Problem Set 1':'Try Exercise 2'}<ArrowRight size={15}/></button></section>)}</div><p className="mindmap-caption"><FlaskConical size={16}/>Every lesson has an experiment, a book reference, a recall check, and space for your own notes.</p></div>;
}
